function buildTags(item) {
  var wrap = document.createElement('div');
  wrap.className = 'tags';
  item.tags.forEach(function (t) {
    var chip = document.createElement('span');
    chip.className = 'tag';
    var label = document.createElement('span');
    label.textContent = t;
    var x = document.createElement('span');
    x.className = 'x'; x.textContent = '×'; x.title = 'Remove tag';
    x.addEventListener('click', function () {
      item.tags = item.tags.filter(function (v) { return v !== t; });
      render();
    });
    chip.appendChild(label); chip.appendChild(x);
    wrap.appendChild(chip);
  });
  if (item.addingTag) {
    var inp = document.createElement('input');
    inp.className = 'taginput'; inp.placeholder = 'tag name';
    inp.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') {
        var v = inp.value.trim().toLowerCase();
        if (v && item.tags.indexOf(v) === -1) item.tags.push(v);
        inp.value = ''; // keep adding
        item._keepAdding = true; render();
      } else if (e.key === 'Escape') { item.addingTag = false; render(); }
    });
    inp.addEventListener('blur', function () {
      var v = inp.value.trim().toLowerCase();
      if (v && item.tags.indexOf(v) === -1) item.tags.push(v);
      item.addingTag = false; render();
    });
    wrap.appendChild(inp);
    setTimeout(function () { inp.focus(); }, 0);
  } else {
    var add = document.createElement('button');
    add.className = 'tagadd';
    add.textContent = item.tags.length ? '+ tag' : '+ add tag';
    add.addEventListener('click', function () { item.addingTag = true; render(); });
    wrap.appendChild(add);
  }
  return wrap;
}

