:root {
  --bg: #f5f6f8;
  --card: #ffffff;
  --line: #e3e6ea;
  --line-strong: #cfd4da;
  --ink: #1c2330;
  --muted: #6b7480;
  --faint: #94a0ad;
  --brand: #2f6fed;
  --brand-dark: #2258c9;
  --brand-soft: #eef3ff;
  --warn: #b26a00;
  --warn-bg: #fff6df;
  --warn-line: #e7cf8f;
  --danger: #c0392b;
  --ok: #2e7d46;
}
* { box-sizing: border-box; }
html, body { margin: 0; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg); color: var(--ink); line-height: 1.45;
}
.wrap { width: 100%; max-width: 760px; margin: 0 auto; padding: 0 16px; }

.app-header { background: var(--card); border-bottom: 1px solid var(--line); padding: 18px 0; }
.app-header h1 { margin: 0; font-size: 22px; }
.tagline { margin: 4px 0 0; color: var(--muted); font-size: 13px; }

main.wrap { padding-top: 20px; padding-bottom: 60px; }

.card-panel, .card {
  background: var(--card); border: 1px solid var(--line); border-radius: 12px;
}
.save { padding: 16px; }
.save-row { display: flex; gap: 10px; flex-wrap: wrap; }
.save-row input {
  flex: 1 1 260px; min-width: 0; padding: 12px; font-size: 15px;
  border: 1px solid var(--line-strong); border-radius: 9px;
}
.save-row button {
  padding: 12px 20px; font-size: 15px; font-weight: 600; cursor: pointer;
  background: var(--brand); color: #fff; border: none; border-radius: 9px;
}
.save-row button:hover { background: var(--brand-dark); }
.readlater-choice {
  display: flex; align-items: center; gap: 8px; margin-top: 12px;
  font-size: 13px; color: var(--muted); cursor: pointer;
}
.readlater-choice input { width: 16px; height: 16px; }
.err { display: none; color: var(--danger); font-size: 13px; margin-top: 10px; }
.err.show { display: block; }
.notice {
  display: none; margin-top: 10px; padding: 10px 12px; font-size: 13px;
  background: var(--warn-bg); border: 1px solid var(--warn-line);
  border-radius: 8px; color: #7a5a00;
}
.notice.show { display: block; }

.controls { margin-top: 20px; }
.search-row { display: flex; gap: 8px; }
.search-row input {
  flex: 1; padding: 11px 12px; font-size: 14px;
  border: 1px solid var(--line-strong); border-radius: 9px; background: #fff;
}
button.ghost {
  padding: 11px 14px; font-size: 14px; cursor: pointer;
  background: #fff; color: var(--muted); border: 1px solid var(--line-strong); border-radius: 9px;
}
button.ghost:hover { background: #f0f2f5; }

.active-filter {
  margin-top: 10px; font-size: 13px; color: var(--muted);
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
}
.active-filter .chip { background: var(--brand-soft); color: #2f5fd0; border-radius: 999px; padding: 3px 10px; font-size: 12px; }
.active-filter .clearf { color: var(--brand); cursor: pointer; text-decoration: underline; background: none; border: none; font-size: 13px; }

.views { display: flex; gap: 6px; margin-top: 14px; flex-wrap: wrap; }
.views .view {
  padding: 8px 15px; font-size: 13px; cursor: pointer;
  background: #fff; color: var(--muted); border: 1px solid var(--line-strong);
  border-radius: 999px; display: inline-flex; align-items: center; gap: 6px;
}
.views .view:hover { background: #f0f2f5; }
.views .view.active { background: var(--brand); color: #fff; border-color: var(--brand); }
.badge { background: var(--brand-soft); color: #2f5fd0; border-radius: 999px; font-size: 11px; padding: 1px 7px; font-weight: 600; }
.views .view.active .badge { background: rgba(255,255,255,.25); color: #fff; }

.list-heading { font-size: 14px; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); margin: 24px 2px 10px; }
.list { list-style: none; padding: 0; margin: 0; }

.card { padding: 14px 16px; margin-bottom: 10px; }
.card.read { opacity: .72; }
.card.flash { animation: flash 1.6s ease; border-color: var(--brand); }
@keyframes flash { 0%,40% { background: var(--warn-bg); } 100% { background: #fff; } }

.titlerow { display: flex; align-items: flex-start; gap: 10px; justify-content: space-between; }
.title { font-size: 16px; font-weight: 600; word-break: break-word; overflow-wrap: anywhere; }
.title.fetching { color: var(--faint); font-style: italic; font-weight: 500; }
.title-edit { flex: 1; font-size: 15px; padding: 7px 9px; border: 1px solid var(--brand); border-radius: 7px; }
.rowactions { display: flex; gap: 8px; flex: none; }
.link { display: inline-block; margin-top: 4px; color: var(--brand); text-decoration: none; font-size: 13px; word-break: break-all; overflow-wrap: anywhere; }
.link:hover { text-decoration: underline; }
.meta { color: var(--faint); font-size: 12px; margin-top: 6px; }
.meta.warn { color: var(--warn); }

.editbtn, .savename {
  border: 1px solid var(--line-strong); background: #fff; color: var(--brand);
  border-radius: 6px; font-size: 12px; padding: 4px 11px; cursor: pointer;
}
.editbtn:hover, .savename:hover { background: #f0f2f5; }
.deletebtn { border: 1px solid #e6c3c0; background: #fff; color: var(--danger); border-radius: 6px; font-size: 12px; padding: 4px 9px; cursor: pointer; }
.deletebtn:hover { background: #fdeeec; }
.confirmdel { display: flex; gap: 8px; align-items: center; font-size: 12px; color: var(--danger); flex-wrap: wrap; }
.confirmdel button { border: none; border-radius: 6px; font-size: 12px; padding: 4px 10px; cursor: pointer; }
.confirmdel .yes { background: var(--danger); color: #fff; }
.confirmdel .no { background: #eceff3; color: var(--muted); }

.tags { margin-top: 10px; display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.tag { background: var(--brand-soft); color: #2f5fd0; border-radius: 999px; font-size: 12px; padding: 3px 10px 3px 11px; display: inline-flex; gap: 6px; align-items: center; }
.tag .label { cursor: pointer; }
.tag .label:hover { text-decoration: underline; }
.tag .x { cursor: pointer; color: #7a92c7; font-weight: 700; }
.tag .x:hover { color: var(--danger); }
.tagadd { border: 1px dashed var(--line-strong); background: #fff; color: var(--muted); border-radius: 999px; font-size: 12px; padding: 3px 12px; cursor: pointer; }
.tagadd:hover { background: #f0f2f5; }
.tagwrap { position: relative; display: inline-block; }
.taginput { font-size: 12px; padding: 4px 9px; border: 1px solid var(--brand); border-radius: 999px; width: 130px; }
.suggest { position: absolute; top: 28px; left: 0; z-index: 5; min-width: 140px; background: #fff; border: 1px solid var(--line-strong); border-radius: 8px; box-shadow: 0 6px 18px rgba(20,30,50,.12); padding: 4px; margin: 0; list-style: none; }
.suggest li { padding: 6px 10px; font-size: 12px; border-radius: 6px; cursor: pointer; color: #2f5fd0; }
.suggest li:hover { background: var(--brand-soft); }

.status { margin-top: 12px; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.addlater { border: 1px dashed var(--line-strong); background: #fff; color: var(--muted); border-radius: 6px; font-size: 12px; padding: 4px 11px; cursor: pointer; }
.addlater:hover { background: #f0f2f5; }
.readtoggle { border: 1px solid var(--line-strong); background: #fff; color: var(--brand); border-radius: 6px; font-size: 12px; padding: 4px 11px; cursor: pointer; }
.readtoggle:hover { background: #f0f2f5; }
.removelater { border: none; background: none; color: var(--faint); font-size: 12px; cursor: pointer; text-decoration: underline; }
.removelater:hover { color: var(--danger); }
.statuslabel { font-size: 12px; font-weight: 600; }
.statuslabel.unread { color: var(--warn); }
.statuslabel.isread { color: var(--ok); }

.empty { text-align: center; color: var(--faint); padding: 36px 20px; border: 1px dashed var(--line-strong); border-radius: 12px; background: #fff; }

@media (max-width: 480px) {
  .save-row button { flex: 1 1 100%; }
  .titlerow { flex-direction: column; }
  .rowactions { align-self: flex-start; }
}

